//! The web assets, compiled into the binary, plus the two classifications
//! every lookup needs: is this path safe, and may an untrusted layer serve it.
//!
//! `ASSETS` is generated by build.rs from `static/`.

include!(concat!(env!("OUT_DIR"), "/assets_table.rs"));

/// Rejects anything that is not a plain relative path.
///
/// The filesystem layers get their confinement from `canonicalize()` +
/// `starts_with(base)`, but the embedded table has no filesystem to
/// canonicalize against, so it needs its own guard. Applied *before* any
/// layer is consulted, so a traversal attempt 404s identically whether or
/// not a filesystem layer is configured — otherwise the difference would
/// reveal which layers are live.
pub fn normalize(rel: &str) -> Option<&str> {
    if rel.is_empty() || rel.starts_with('/') || rel.contains('\\') {
        return None;
    }
    for seg in rel.split('/') {
        if seg.is_empty() || seg == "." || seg == ".." {
            return None;
        }
    }
    Some(rel)
}

pub fn get(rel: &str) -> Option<&'static [u8]> {
    let rel = normalize(rel)?;
    ASSETS.binary_search_by(|(k, _)| (*k).cmp(rel)).ok().map(|i| ASSETS[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_carries_the_real_files() {
        let js = get("app.js").expect("app.js must be embedded");
        let disk = std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"), "/static/app.js")).unwrap();
        assert_eq!(js, &disk[..], "embedded bytes must match the file on disk");
        assert!(get("style.css").is_some());
        assert!(get("themes/darcula.css").is_some(), "nested paths must be reachable");
        assert!(get("vendor/xterm.js").is_some());
        assert!(get("nope.js").is_none());
    }

    #[test]
    fn the_table_is_sorted_so_binary_search_is_valid() {
        let keys: Vec<&str> = ASSETS.iter().map(|(k, _)| *k).collect();
        let mut sorted = keys.clone();
        sorted.sort();
        assert_eq!(keys, sorted, "build.rs must emit a sorted table");
    }

    #[test]
    fn normalize_rejects_every_way_out_of_the_tree() {
        assert!(normalize("app.js").is_some());
        assert!(normalize("themes/dark.css").is_some());
        assert_eq!(normalize(""), None);
        assert_eq!(normalize("/etc/passwd"), None);
        assert_eq!(normalize("../Cargo.toml"), None);
        assert_eq!(normalize("themes/../../Cargo.toml"), None);
        assert_eq!(normalize("./app.js"), None);
        assert_eq!(normalize("a//b.css"), None);
        assert_eq!(normalize("a\\..\\b"), None);
        // and the same guard covers `get`
        assert!(get("../Cargo.toml").is_none());
    }
}
